import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易辨畫","description":"周易辨畫 - 周易辨畫","frontmatter":{"title":"周易辨畫","description":"周易辨畫 - 周易辨畫"},"headers":[],"relativePath":"classics/bianhua/001.md","filePath":"classics/bianhua/001.md"}'),r={name:"classics/bianhua/001.md"};function i(n,p,c,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易辨畫" tabindex="-1">周易辨畫 <a class="header-anchor" href="#周易辨畫" aria-label="Permalink to “周易辨畫”">​</a></h1><p>欽定四庫全書經部一</p><p>易類提要</p><p>臣 等謹案：周易辨畫四十卷，</p><p>國朝連斗山撰。斗山字叔度，潁州人。是書大旨謂一卦之義在於爻，爻畫有剛有柔，因剛柔之畫而立之象，即因剛柔之畫而系以詞。其道先在於辨畫，故以為名。末有輯圖一卷，則即朱子舊圖而略為損益之。其說專主卦畫立義，如屯之大象雲四偶以次條列，如絲中貫一奇，如梭上互艮手，下動震足，如織絍然。經綸之象，未免穿鑿太甚。然其逐卦詳列互體，剖析微渺，亦頗有合於精理者。蓋即爻論爻，乃能以易詮易，雖間有附會之失，而錯綜變化之本旨，猶可藉以參觀。固與高談性道以致惝恍無歸者，尚較有實際焉。乾隆四十四年八月恭校上。</p><p>總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。周易辨畫提綱</p><p>看易當以象為主。繫辭傳曰：</p><p>「古者包犧氏之王天下也，仰則觀象於天，俯則觀法於地，觀鳥獸之文與地之宜，近取諸身，遠取諸物，於是始作八卦，以通神明之德，以類萬物之情。」又曰：「易者，象也。象也者，像也。」又曰：「聖人立象以盡意。」是易之有象，乃易之所以為易也。自兩漢諸儒泥於象數之學，創為五行、納甲、飛伏之法，往往至於穿鑿傅會而失其正。於是王氏弼注出，一掃而空之，至謂「得象可以忘言，得意並可以忘象」，又未免矯枉太甚。夫書不盡言，言不盡意，聖人乃立象以盡意。象苟不知，何以知言？言苟不知，何以知意？故朱子曰：「看易若是靠定象去看，便滋味長；若只恁地懸空看，也沒甚意思。」又曰：「說易得其理，則象數在其中。」固是如此。然溯流以觀，卻須先見得象數的當下落，方說理不走作。不然，事無實證，則虛理易差也。此言可謂得讀易之法。</p><p>易為卜筮之書，乃聖人吉凶與民同患，欲人趨吉避凶也。其事原為日用平常之事，其理即為日用平常之理，乃百姓可以與能者。故繫辭傳曰：</p><p>「易之為書也，不可遠。」又曰：「無有師保，如臨父母。」雖其中大無不包，精無不入，而依象明義，總宜說得淺近。愈淺近愈見精微，方是聖人覺世牖民之意。若謂易道陰陽，說入玄遠幽深，先與聖人本意不符，安得與卦爻象義相符也？諸家說易，往往似因此反失。</p><p>彖乃統舉一卦之義。一卦之義何在？在諸爻也。故繫辭傳曰：「彖者，材也。」又曰：「彖者，言乎象者也。」</p><p>「聖人有以見天下之賾，而擬諸其形容，象其物宜，是故謂之象。」夫所謂材者，即卦中剛柔之畫也。所謂象者，亦即卦中剛柔之畫也。因剛柔之畫而立之為象，即因剛柔之畫而繋之以辭也。所以曰：「知者觀其彖辭，則思過半矣。」不然，彖中之畫不清，即爻中之義不明，何以觀其彖辭則思過半？故卦辭必要先知其所指何爻，夫然後文周之旨，分合一律，爻乃析舉一爻之義。一爻之義何在？在貞與不貞也。故繫辭傳曰：「爻者，效天下之動者也。天下之動，貞夫一者也。」蓋天下之動不一，而動之之理，不過期人皆歸於貞。其得爻之貞者必吉，其得爻之不貞者必兇，故曰：「吉凶，貞勝者也。」一部周易，皆不出此一字。</p><p>初爻本一，上爻本六，其不曰一、六而曰初、上者，一不過數之開端，六亦非數之究竟，與一卦六爻之位無取也，故謂之曰「初」，則天時之履端，人事之肇基，俱於是乎在。此二爻不以一人一事言，觀繫辭傳曰：「其初難知，其上易知，本末也。」初辭擬之，卒成之，終可知。</p><p>中四爻乃詳論卦辭中之義，繫辭傳所謂「雜物撰德，辨是與非」者也。析而論之，一爻自為一義。總而言之，爻爻期於當位而已。其有當位而不雲吉，不當位而反雲吉者，義自具於「上下無常」、「剛柔相易」中，不在本爻也。至二、四同功，三、五同功之互義，則前人已言之。然漢亦有以四爻、五爻連互者，如虞氏易以豫卦初至五為比，故「利建侯」；三至上為師，故「利行師」是也。</p><p>卦變之說，自昔云然，而程子非之，朱子取之，先儒亦互有議論。竊以卦之自來，出於乾、坤，與出於否、泰，其理無二，總不外於繫辭傳「變動不居，周流六虛，上下無常，剛柔相易，不可為典要，惟變所適」數語。聖人既分言於各彖、爻之中，復總括於繫辭傳之內，其教人以讀易之法，亦明且盡矣。而解者猶執本爻之辭，以為本爻解，無怪乎所解者之不可解也。漢、魏以來，如荀氏爽、虞氏翻諸家，多窺其妙，而義涉隱晦，象近穿鑿，未能一歸醇正。今雖偶用其意，而義必期傳與經協，經與卦協，使四聖人之意若合符節，乃敢以系傳之說，一為上下，一為相易，以定一解。然其道亦無他，仍即前所云貞一而已矣。蓋卦中諸爻之所以上下無常、剛柔相易者，皆以求其貞者也。</p><p>易自上下無常、剛柔相易而外，又有錯綜與旁通之法。所謂錯者，即上下兩卦交易之謂也，如水雷屯、雷水解是也。所謂綜者，即一卦六爻顛倒之謂也，如水雷屯、山水蒙是也。所謂旁通者，即此卦通於彼卦之謂，如比與大有是也。凡易至不可上下、不可錯綜處，則其義為窮，窮則旁通焉。系傳所云「易窮則變，變則通」，即旁通也。卦有主爻，有應爻，有乘承。比與爻，前人論之已悉，不敢復贅。</p><p>易經二篇，傳十篇，在古原自分編，自鄭氏玄、王氏弼以傳附經，始失其舊。但經後列傳，便於檢閱，故茲編尚仍之未改焉。</p>',17)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
